// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2022, "4-5", [{"author":"И. Иткин","question":"Простую задачу конкурса «Русский медвежонок» можно решить за одну минуту, а задачу посложнее — __________.","choices":["за полтору минуту","за полтора минута","за полторы минуты","за полторе минуте","за полтор минут."],"key":"В","review":["Время на задачу","«Минута» — слово женского рода, поэтому выбираем «полторы», как в выражении «полторы недели».","После «полторы» нужна форма родительного падежа единственного числа: «минуты». Получается «за полторы минуты»."]},{"author":"О. Подлесская","question":"Что может запрещать этот знак?","choices":["вынос собак","выход собак","выгул собак","выпас собак","выезд собак."],"key":"В","review":["Перечёркнутая собака","На знаке собака в перечёркнутом круге. Такая черта показывает запрет, а рисунок подсказывает, с кем он связан.","Прогулку с собакой называют выгулом. «Выпас» относится к пастбищу, «вынос» — к переноске, а «выезд» — к поездке. «Выход» обозначал бы только пересечение выхода. На знаке подразумевается запрет выгула собак."],"figure":{"condition":{"src":"assets/medvezhonok/2022/4-5-2.webp","width":204,"height":204,"pixelWidth":204,"pixelHeight":204,"alt":"Силуэт собаки в красном перечёркнутом круге."}}},{"author":"Е. Муравенко","question":"Найдите лишнее по смыслу.","choices":["<em>чашка</em>","<em>кружка</em>","<em>стакан</em>","<em>бокал</em>","<em>тарелка</em>."],"key":"Д","review":["Лишняя посуда","Представь, куда можно налить чай, сок или воду, чтобы пить. Для этого подходят чашка, кружка, стакан и бокал.","Тарелка тоже посуда, но из неё обычно едят. По назначению она отличается от остальных четырёх предметов."]},{"author":"А. Панина","question":"В каком слове приставка не такая, как в остальных?","choices":["<em>подножный</em>","<em>подвижный</em>","<em>поддельный</em>","<em>подпольный</em>","<em>подсудный</em>."],"key":"Б","review":["Разбор приставок","Найди родственные слова: «нога» для «подножный», «делать» для «поддельный», «пол» для «подпольный», «суд» для «подсудный». Во всех четырёх приставка «под-».","У «подвижный» родственные слова «двигать» и «движение». Буква Д уже в корне «движ-», поэтому приставка здесь «по-»."]},{"author":"И. Рубанов","question":"<em>У нас много</em> __________.\nС каким из этих продолжений получится осмысленная фраза?","choices":["<em>вкусов этого вкуса</em>","<em>запахов этого запаха</em>","<em>звуков этого звука</em>","<em>касаний этого касания</em>","<em>цветов этого цвета</em>."],"key":"Д","review":["Повтор со смыслом","В каждой фразе проверь значение слова во множественном числе и после «этого». У слов «вкус», «запах», «звук» и «касание» повторяется один и тот же смысл.","«Цветов» может быть формой слова «цветок», а «цвета» — формой слова «цвет». «Много цветов этого цвета» значит, что много цветов одной окраски."]},{"author":"И. Рубанов","question":"Какое из этих утверждений означает совсем не то, что остальные?","choices":["<em>Лежу на диване</em>.","<em>Лежу на кровати</em>.","<em>Лежу на песке</em>.","<em>Лежу на солнышке</em>.","<em>Лежу на травке</em>."],"key":"Г","review":["Где можно лежать","Сравни, на чём лежит человек. Диван, кровать, песок и трава обозначают поверхность под ним.","«Лежу на солнышке» означает «лежу там, где светит солнце». Солнце освещает человека, а лежать он может, например, на траве."]},{"author":"Л. Фёдорова","question":"<em>Портниха</em>, <em>ткачиха</em>, <em>повариха</em> — названия женщин по профессии. Для какого из слов однокоренное название мужчины соответствующей профессии устроено не так, как остальные?","choices":["для <em>портниха</em>","для <em>ткачиха</em>","для <em>повариха</em>","для всех этих слов названия мужчин по профессии однотипны","у этих профессий нет специальных названий для мужчин."],"key":"А","review":["Профессии и названия","Подбери мужские названия профессий к «портниха», «ткачиха» и «повариха». Получатся «портной», «ткач» и «повар».","Из «ткачиха» и «повариха» достаточно убрать «-иха». У «портнихи» после удаления «-иха» остаётся «портн-». Чтобы получилось «портной», надо ещё добавить окончание «-ой»."]},{"author":"О. Подлесская","question":"В какой паре слова́ соотносятся между собой по смыслу не так, как в остальных четырёх парах?","choices":["<em>бубенцы</em> — <em>бубенчики</em>","<em>вагоны</em> — <em>вагончики</em>","<em>коридоры</em> — <em>коридорчики</em>","<em>счёты</em> — <em>счётчики</em>","<em>огурцы</em> — <em>огурчики</em>."],"key":"Г","review":["Похожие пары слов","Попробуй к каждому второму слову подобрать смысл «маленькие такие же». Получаются маленькие бубенцы, вагоны, коридоры и огурцы.","Счёты — рамка с костяшками для вычислений, а счётчики — приборы или устройства, которые что-то подсчитывают. Это разные вещи, поэтому пара отличается."]},{"author":"И. Рубанов","question":"Если самец — селезень, то кто самка?","choices":["<em>селезёнка</em>","<em>селезниха</em>","<em>утка</em>","<em>цесарка</em>","<em>селезень</em> — это камень, у него не может быть самки."],"key":"В","review":["Пара для селезня","Вспомни, какую водоплавающую птицу называют селезнем. Это название самца, которого можно увидеть рядом с утятами.","Самка селезня — утка. Цесарка — другая птица, а «селезёнка» обозначает орган."]},{"author":"О. Подлесская","question":"Для работы ему нужна особая печь, наковальня и молот. Это _____.","choices":["гончар","кузнец","мельник","пекарь","печник."],"key":"Б","review":["Печь, молот и наковальня","Свяжи печь с двумя другими орудиями. На наковальню кладут разогретый металл и бьют по нему молотом, придавая форму.","Так работает кузнец. Печь может пригодиться и пекарю, но наковальня и молот выдают кузнечную работу."]},{"author":"Б. Иомдин","question":"<em>В семье Осьминогов ужасная драма:\nЗа завтраком ссорятся Папа и Мама,\nА бедные Детки стоят на пороге\nИ просят родителей взять себя в ноги.</em>\nБоря прочитал это стихотворение Ренаты Мухи и решил переделать для осьминогов и другие выражения. Какое выражение оказалось и так существующим?","choices":["<em>положа ногу на сердце</em>","<em>ноги отваливаются</em>","<em>сидеть сложа ноги</em>","<em>ноги в боки</em>","<em>всплеснуть ногами</em>."],"key":"Б","review":["Выражения для осьминогов","В четырёх фразах попробуй восстановить «руки»: «положа руку на сердце», «сидеть сложа руки», «руки в боки», «всплеснуть руками». Так обычно говорят люди.","«Ноги отваливаются» и без замены говорят после долгой ходьбы. Эта фраза означает, что ноги очень устали."]},{"author":"И. Рубанов","question":"<em>Стометровка</em>, <em>сторублёвка</em>, ...\nКакое слово естественно добавить к этому списку?","choices":["<em>столетник</em>","<em>столик</em>","<em>столица</em>","<em>стопа</em>","<em>сторож</em>."],"key":"А","review":["Слова со «сто»","Разверни «стометровка» и «сторублёвка» в подсказки: сто метров и сто рублей. Начало «сто» в них означает число.","«Столетник» также связан с числом сто: в слове можно увидеть «сто лет». В «столике», «столице», «стопе» и «стороже» такого значения нет."]},{"author":"Л. Фёдорова","question":"Какое имя сказочного героя не связано по происхождению с глаголом?","choices":["<em>Айболит</em>","<em>Пилюлькин</em>","<em>Незнайка</em>","<em>Щелкунчик</em>","<em>Несмеяна</em>."],"key":"Б","review":["Сказочные имена","Найди действия, которые слышны в именах: болит у Айболита, знать у Незнайки, щёлкать у Щелкунчика и смеяться у Несмеяны.","Пилюлькин назван по пилюлям — лекарству, которое прописывает доктор. «Пилюля» — название предмета, поэтому имя отличается от остальных."]},{"author":"И. Рубанов","question":"<em>Противень</em> — это __________.","choices":["металлический лист с загнутыми краями для приготовления пищи","неприятный человек","дом напротив","вид слизня","полоса встречного движения на загородном шоссе."],"key":"А","review":["Что такое противень","Вспомни, на чём раскладывают печенье перед тем, как поставить его в духовку. В рецептах часто просят «застелить противень бумагой».","Противень — металлический лист с загнутыми краями для выпечки и другого приготовления пищи. Слова «противный» и «напротив» только похожи на его название."]},{"author":"Л. Фёдорова","question":"Какого слова нет в современном литературном языке?","choices":["<em>осмотр</em>","<em>присмотр</em>","<em>просмотр</em>","<em>рассмотр</em>","<em>недосмотр</em>."],"key":"Г","review":["Слова со «смотр»","Проверь слова в знакомых сочетаниях: осмотр врача, присмотр за детьми, просмотр фильма, недосмотр дежурного.","Для действия «рассмотреть» литературное существительное — «рассмотрение», например «рассмотрение заявления». «Рассмотр» здесь в норму не входит."]},{"author":"Л. Фёдорова","question":"«Утереть _____ и при этом не остаться с _____ ― большое искусство!» В этой цитате из сказки «Приключения капитана Селёдкина» В. В. Лебедева мы пропустили одно слово в разных падежах; какое?","choices":["<em>слеза</em>","<em>пот</em>","<em>кровь</em>","<em>лоб</em>","<em>нос</em>."],"key":"Д","review":["Утереть и остаться","Найди устойчивые выражения. «Утереть кому-то нос» значит показать, что ты умеешь делать что-то лучше него.","«Остаться с носом» значит не получить того, на что надеялся. Одно слово подходит в оба места: «утереть нос» и «остаться с носом»."]},{"author":"Л. Фёдорова","question":"Можно сказать: <em>его</em> (<em>её</em>, <em>их</em>, <em>ничей</em>) <em>мяч</em>. Маленький Вова образует от всех этих местоимений слова на <em>-ний/-ный</em>. В каком случае у него получится слово литературного языка?","choices":["в каждом","только в случае <em>их</em>","только в случае <em>ничей</em>","только в случаях <em>их</em> и <em>ничей</em>","ни в одном."],"key":"В","review":["Чей мяч","По очереди добавь нужный конец: «егошний», «еёшний», «ихний», «ничейный». Послушай, какие варианты остаются привычными только в разговоре.","В литературной речи говорят «его мяч», «её мяч», «их мяч». А вариант «ничейный мяч» допустим и означает, что мяч никому не принадлежит."]},{"author":"П. Аркадьев","question":"Какое слово образовано иначе, чем другие?","choices":["<em>звукопись</em>","<em>клинопись</em>","<em>перепись</em>","<em>рукопись</em>","<em>скоропись</em>."],"key":"В","review":["Как образованы слова","Раздели «звукопись», «клинопись», «рукопись» и «скоропись» на смысловые части. До «-пись» в них есть слова или основы «звук», «клин», «рука», «скоро».","У «переписи» в основе только один корень «-пись», перед ним стоит приставка «пере-». В остальных четырёх словах соединены две основы."]},{"author":"Л. Фёдорова","question":"Согласные звуки бывают звонкие, глухие, твёрдые, мягкие, а ещё шипящие. А какое из этих слов содержит только те согласные звуки, которые называет?","choices":["<em>звонкие</em>","<em>глухие</em>","<em>твёрдые</em>","<em>мягкие</em>","<em>шипящие</em>."],"key":"Г","review":["Согласные о себе","Прочитай каждое слово вслух. В «звонкие» слышен глухой [к’], в «глухие» — звонкий [г], в «твёрдые» — мягкий [в’], а в «шипящие» слышны [п’] и [й’], которые не шипят.","В «мягкие» звучат мягкие согласные [м’], [х’], [к’] и [й’]. Поэтому только это слово по своему звучанию подходит под собственное название."]},{"author":"О. Подлесская","question":"Как известно, <em>арена</em> — это площадка для представлений в цирке. А что означает arena по-испански?","choices":["лёд","вода","снег","песок","камень."],"key":"Г","review":["Арена по-испански","Представь древнюю арену, где проходили состязания. Такую площадку могли посыпать сыпучим материалом, который легко разровнять.","Испанское arena означает «песок». У русского «арена» осталось другое значение — сама площадка для зрелищ."]},{"author":"Е. Муравенко","question":"В какой паре второе слово состоит <strong>не</strong> из тех же звуков, что и первое?","choices":["<em>краб — брак</em>","<em>карп — парк</em>","<em>клоп — полк</em>","<em>рост — сорт</em>","<em>шрам — марш</em>."],"key":"А","review":["Звуки в парах слов","Произнеси пару «краб — брак». На конце слова «краб» слышится глухой [п], а в начале слова «брак» — звонкий [б].","Пары «карп — парк», «клоп — полк», «рост — сорт» и «шрам — марш» переставляют тот же набор звуков. В «краб — брак» набор изменился из-за оглушения."]},{"author":"С. Дьяченко","question":"В каком из этих слов ударение может падать на первый слог?","choices":["<em>обоими</em>","<em>двумя</em>","<em>четырьмя</em>","<em>восемью</em>","<em>двенадцатью</em>."],"key":"Г","review":["Ударение в числительных","Произнеси варианты: обои́ми, двумя́, четырьмя́, двена́дцатью. Ни в одном из них ударный слог не первый.","Произнеси «во́семью» с ударением на «во». Это допустимое произношение, поэтому подходит «восемью»."]},{"author":"И. Иткин и С. Переверзева","question":"Многие люди иногда в шутку вместо «яблоко» говорят «тыблоко». Однажды Маша сказала мужу: «Как пойдёшь в магазин, не забудь купить <em>тыблоки</em> и <em>сливы</em>». <em>—</em> «Тогда уж <em>тыблоки</em> и _____», <em>—</em> рассмеялся муж. Какое слово мы пропустили?","choices":["<em>слиты</em>","<em>сливки</em>","<em>слимы</em>","<em>слия</em>","<em>высли</em>."],"key":"В","review":["Тыблоки и сливы","Сравни «яблоко» и «тыблоко». Шутка устроена так, будто в начале слова было местоимение «я» и его заменили на «ты».","В конце «сливы» спряталось «вы». Во множественном числе к нему подходит та же замена «мы», и получается «слимы»."]},{"author":"С. Дьяченко","question":"Первокласснице Насте купили компьютерный стул. Однажды Настя собиралась делать уроки и обнаружила, что со стулом кое-что не так. Она возмущённо спросила маму: __________","choices":["Кто обидел мой стул?","Кто оскорбил мой стул?","Кто унизил мой стул?","Кто обругал мой стул?","Кто ущемил мой стул?"],"key":"В","review":["Настин стул","У компьютерного стула можно регулировать высоту сиденья. Представь, что Настя увидела своё сиденье ниже обычного.","Настя поняла «унизил» как «сделал ниже». Обычно «унизить» значит оскорбить чьё-то достоинство, и в этом шутка."]},{"author":"Л. Фёдорова","question":"В сказке Виталия Бианки «Чей нос лучше?» у птиц разнообразные прозвища. Какое из них описывает птичий нос несколько иначе, чем остальные?","choices":["<em>Тонконос</em>","<em>Крестонос</em>","<em>Крючконос</em>","<em>Серпонос</em>","<em>Шилонос</em>."],"key":"А","review":["Птичьи прозвища","Разбери имена Крестонос, Крючконос, Серпонос и Шилонос. Их первые части называют предметы, с которыми сравнивают форму клюва.","В «Тонконос» первая часть передаёт толщину клюва. Здесь клюв описан напрямую, без сравнения с предметом."]},{"author":"А. Остроумова","question":"Одна компьютерная программа не знает русские фамилии и подчёркивает их как несуществующие слова. Однако среди следующих фамилий одну фамилию она не подчеркнёт. Какая это фамилия?","choices":["<em>Соловьёв</em>","<em>Золотарёв</em>","<em>Рублёв</em>","<em>Снегирёв</em>","<em>Сычёв</em>."],"key":"А","review":["Слово или фамилия","Попробуй прочитать каждую фамилию с маленькой буквы. Спроси «нет кого?» от названий птиц: «снегирей», «сычей», «соловьёв».","Фамилия «Соловьёв» совпадает с формой «соловьёв» в выражении «много соловьёв». Поэтому программа примет её за знакомое слово."]},{"author":"Е. Туманова","question":"Девочка Маша придумала сказку. В Машином волшебном мире живут: чуткая тучка, солнечный слон, величественный лев, сильный лис, ловкий волк и __________.","choices":["жёлтенький ёжик","быстрая рыба","умная пума","проворная корова","неторопливый енот."],"key":"Д","review":["Машин волшебный мир","Возьми из начала признака столько букв, сколько их в следующем слове. Из «чутка» получится «тучка», из «солн» — «слон», из «вел» — «лев», из «сил» — «лис», из «ловк» — «волк».","«Неторопливый» начинается с «нето», из этих четырёх букв складывается «енот». Остальные признаки не начинаются с набора букв своих существительных."]},{"author":"И. Иткин и Л. Иткин","question":"Папа с сыном играли в слова. Они по очереди называли существительные так, чтобы каждое следующее начиналось на две последних буквы предыдущего (например: <em>гол<strong>ос</strong> — <strong>ос</strong>и<strong>на</strong> — <strong>на</strong>деж<strong>да</strong>...</em>). Сын сделал ход. «Ну, тут и думать нечего!» — воскликнул папа. — «Кого она ест?» И сделал свой ход.\nНа какие буквы начиналось слово, которое назвал сын?","choices":["на <em>ак</em>","на <em>ла</em>","на <em>мы</em>","на <em>пт</em>","на <em>ца</em>."],"key":"Д","review":["Ход папы в игре","Папа ищет добычу животного, названного сыном. Название добычи должно начинаться на те две буквы, которыми заканчивается слово сына.","«Цапля» заканчивается на «ля», а цапля ест лягушек. Ход «цапля — лягушка» получается по правилу, значит, сын начал слово с «ца»."]},{"author":"Е. Дубосарская и И. Иткин","question":"У поэта Саши Чёрного есть стихотворение «Живая азбука», включающее в себя двустишия, каждая строка которых начинается на одну и ту же букву, например:\n<em>Астра в садике цветёт ―\nАист, вам пора в поход!</em>\nКакого из следующих двустиший на самом деле нет в «Азбуке» Саши Чёрного?","choices":["<em>Гусь шагает, как солдат.\nГруша зреет ― Гриша рад.</em>","<em>Дятел в дуб всё тук да тук…\nДуб скрипит: «Что там за стук?»</em>","<em>Кот боится наших пчёл.\nКнигу Коленька прочёл.</em>","<em>Ослик влез в чертополох.\nОбезьянки ищут блох.</em>","<em>Пчёлка трудится весь день,\nПетушку и клюнуть лень.</em>"],"key":"В","review":["Двустишия азбуки","Сравни первые слова строк. Все пары начинаются на одну букву, но у Саши Чёрного эти слова связаны с чем-то живым: гусь и груша, дятел и дуб, ослик и обезьянки, пчёлка и петушок.","Книга — неживой предмет, поэтому двустишие про кота и книгу выбивается из ряда. В настоящих строках на К через мост бежит крыса, а за ней кот."]},{"author":"Б. Иомдин","question":"Миша, гуляя по городку Йиндржихув-Градец в Южной Чехии (Jindřichův Hradec, Jihočeský kraj), увидел надписи на окне булочной и стал выбирать, что бы ему съесть. Что ему не подойдёт, потому что это напиток?","choices":["koláč","chlebíček","rohlík","bulka","káva."],"key":"Д","review":["Надписи на булочной","Присмотрись к знакомым частям: chlebíček похоже на «хлеб», bulka — на «булка», а rohlík напоминает слово «рогалик». Это всё выпечка или изделия из хлеба.","Koláč — пирог, а káva — кофе. Кофе пьют, поэтому напиток — káva."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
